using System.Runtime.InteropServices;
namespace LSE.AutoCADElectrical.CatalogTools;
public sealed class AccessCatalogService {
 readonly string path; public AccessCatalogService(string p)=>path=p;
 dynamic Open(bool writable=false){if(!File.Exists(path))throw new FileNotFoundException("Catalog database was not found.",path);Type t=Type.GetTypeFromProgID("ADODB.Connection")??throw new InvalidOperationException("ADODB unavailable.");dynamic c=Activator.CreateInstance(t)!;var errors=new List<string>();foreach(string p in new[]{"Microsoft.ACE.OLEDB.16.0","Microsoft.ACE.OLEDB.12.0","Microsoft.Jet.OLEDB.4.0"})try{c.Open($"Provider={p};Data Source={path};Persist Security Info=False;");return c;}catch(Exception ex){errors.Add(p+": "+ex.Message);}Release(c);throw new InvalidOperationException(string.Join(Environment.NewLine,errors));}
 public List<string> GetTables(){dynamic c=Open(),r=null!;try{r=c.OpenSchema(20);var x=new List<string>();while(!r.EOF){string n=Convert.ToString(r.Fields[2].Value)??"",k=Convert.ToString(r.Fields[3].Value)??"";if(k.Equals("TABLE",StringComparison.OrdinalIgnoreCase)&&!n.StartsWith("MSys")&&!n.StartsWith("_"))x.Add(n);r.MoveNext();}return x.OrderBy(FamilyNames.Friendly).ToList();}finally{Release(r);try{c.Close();}catch{}Release(c);}}
 public List<CatalogRecord> ReadTable(string table,int limit=20000){ValidateTable(table);dynamic c=Open(),r=null!;try{r=c.Execute($"SELECT TOP {limit} * FROM [{table}]");var x=new List<CatalogRecord>();while(!r.EOF){var z=new CatalogRecord{TableName=table};for(int i=0;i<r.Fields.Count;i++){string n=Convert.ToString(r.Fields[i].Name)??"";object v=r.Fields[i].Value;z.Values[n]=v is null or DBNull?"":Convert.ToString(v)?.Trim()??"";}x.Add(z);r.MoveNext();}return x;}finally{Release(r);try{c.Close();}catch{}Release(c);}}
 public CatalogRecord? FindByKey(string key){var p=key.Split('|'); if(p.Length<3)return null;return ReadTable(p[0]).FirstOrDefault(x=>x.Key.Equals(key,StringComparison.OrdinalIgnoreCase));}
 public void AddRecord(CatalogAddRequest q){ValidateTable(q.TableName);dynamic c=Open(true),schema=null!;try{schema=c.Execute($"SELECT TOP 1 * FROM [{q.TableName}]");var cols=new HashSet<string>(StringComparer.OrdinalIgnoreCase);for(int i=0;i<schema.Fields.Count;i++)cols.Add(Convert.ToString(schema.Fields[i].Name)??"");Release(schema);schema=null!;
  var values=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase){{"CATALOG",q.Catalog},{"MANUFACTURER",q.Manufacturer},{"DESCRIPTION",q.Description},{"TYPE",q.Type},{"RATING",q.Rating},{"USER1",q.User1},{"USER2",q.User2},{"USER3",q.User3},{"TEXTVALUE",q.TextValue},{"WDBLKNAM",q.WdBlkNam}};
  var use=values.Where(k=>cols.Contains(k.Key)).ToList(); string names=string.Join(",",use.Select(k=>$"[{k.Key}]"));string vals=string.Join(",",use.Select(k=>$"'{k.Value.Replace("'","''")}'"));c.Execute($"INSERT INTO [{q.TableName}] ({names}) VALUES ({vals})");
 }finally{Release(schema);try{c.Close();}catch{}Release(c);}}
 public bool Exists(string table,string mfg,string cat)=>ReadTable(table).Any(x=>x.Manufacturer.Equals(mfg,StringComparison.OrdinalIgnoreCase)&&x.Catalog.Equals(cat,StringComparison.OrdinalIgnoreCase));
 static void ValidateTable(string t){if(!System.Text.RegularExpressions.Regex.IsMatch(t,"^[A-Za-z0-9_]+$"))throw new InvalidOperationException("Invalid table name.");}
 static void Release(object? o){if(o!=null&&Marshal.IsComObject(o))try{Marshal.FinalReleaseComObject(o);}catch{}}
}
